Kai: Draft Python snippet:
```
from redwood import Redwood
import time, random
client = Redwood()

def retry_simple(fn, tries=3):
  for i in range(tries):
    try:
      return fn()
    except Exception:
      time.sleep(min(2**i + random.random(), 6))
  raise

for page in client.responses.paginate(model='rw-small', page_size=2):
  for chunk in client.responses.stream(page.cursor):
    print(getattr(chunk, 'text', '') or getattr(chunk, 'delta', ''))

# safe create with idempotency key
resp = retry_simple(lambda: client.responses.create(model='rw-small', input='hi', idempotency_key='op-123'))
print(resp)
```
